#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/gpio.h>
#include <zephyr/shell/shell.h>
#include <stdatomic.h>

#define LED0_NODE DT_ALIAS(led0)
#define LED0_GPIO_LABEL DT_GPIO_LABEL(LED0_NODE, gpios)
#define LED0_GPIO_PIN DT_GPIO_PIN(LED0_NODE, gpios)
#define LED0_GPIO_FLAGS DT_GPIO_FLAGS(LED0_NODE, gpios)

#define BLINK_THREAD_STACK_SIZE 512
#define BLINK_THREAD_PRIORITY 5

static const struct gpio_dt_spec led = GPIO_DT_SPEC_GET(LED0_NODE, gpios);
static atomic_bool blink_enabled = ATOMIC_VAR_INIT(false);

static void blink_thread_fn(void *arg1, void *arg2, void *arg3)
{
    ARG_UNUSED(arg1);
    ARG_UNUSED(arg2);
    ARG_UNUSED(arg3);

    while (1) {
        if (atomic_load(&blink_enabled)) {
            gpio_pin_toggle_dt(&led);
            k_sleep(K_MSEC(500));
        } else {
            k_sleep(K_MSEC(100));
        }
    }
}

K_THREAD_DEFINE(blink_thread, BLINK_THREAD_STACK_SIZE,
                blink_thread_fn, NULL, NULL, NULL,
                BLINK_THREAD_PRIORITY, 0, 0);

static int cmd_blink_on(const struct shell *sh, size_t argc, char **argv)
{
    ARG_UNUSED(argc);
    ARG_UNUSED(argv);

    atomic_store(&blink_enabled, true);
    shell_print(sh, "BLINK ON");
    return 0;
}

static int cmd_blink_off(const struct shell *sh, size_t argc, char **argv)
{
    ARG_UNUSED(argc);
    ARG_UNUSED(argv);

    atomic_store(&blink_enabled, false);
    gpio_pin_set_dt(&led, 0);
    shell_print(sh, "BLINK OFF");
    return 0;
}

static int cmd_blink_status(const struct shell *sh, size_t argc, char **argv)
{
    ARG_UNUSED(argc);
    ARG_UNUSED(argv);

    if (atomic_load(&blink_enabled)) {
        shell_print(sh, "BLINK STATUS: ON");
    } else {
        shell_print(sh, "BLINK STATUS: OFF");
    }
    return 0;
}

SHELL_STATIC_SUBCMD_SET_CREATE(sub_blink,
    SHELL_CMD(on, NULL, "Enable blink", cmd_blink_on),
    SHELL_CMD(off, NULL, "Disable blink", cmd_blink_off),
    SHELL_CMD(status, NULL, "Check blink status", cmd_blink_status),
    SHELL_SUBCMD_SET_END
);

SHELL_CMD_REGISTER(blink, &sub_blink, "Blink commands", NULL);

int main(void)
{
    if (!gpio_is_ready_dt(&led)) {
        return -1;
    }

    gpio_pin_configure_dt(&led, GPIO_OUTPUT_INACTIVE);

    return 0;
}

